import React from 'react';
import dogeComrade from '../assets/doge-comrade.png';

const Developers = () => {
  return (
    <div className="min-h-screen bg-gradient-to-b from-[#0B041A] to-mystery-dark flex items-center justify-center">
      <div className="container mx-auto px-4 py-16 flex flex-col lg:flex-row items-center">
        {/* Left side - Doge Comrade image */}
        <div className="lg:w-1/2 mb-8 lg:mb-0 flex justify-center">
          <img 
            src={dogeComrade} 
            alt="Doge Comrade" 
            className="w-full max-w-[500px] mx-auto"
          />
        </div>
        
        {/* Right side - Catchphrase and developer list */}
        <div className="lg:w-1/2 text-center lg:text-left lg:pl-10">
          <h2 className="font-heading text-4xl text-white mb-4">
            This site is developed by 2 comrades! 🐕
          </h2>
          <p className="font-body text-lg text-gray-300 mb-6">
            We are passionate about memes and technology, bringing you the best experience!
          </p>
          <ul className="font-heading text-xl text-gray-300 list-disc list-inside space-y-2">
            <li>PHAM VU MINH - Software Engineering</li>
            <li>DINH LE HOANG ANH - Data Analyst</li>
          </ul>
        </div>
      </div>
    </div>
  );
};

export default Developers;
